INSERT INTO public.advanced_page_content(id,landing_page_id,content,created_at,updated_at) VALUES
('3f08d811-8dfe-4d26-86de-4478d6da13a9','ba0c2b29-2e90-43e9-97da-c77a9429c2f5','{"faq": {"faqs": [{"answer": "Sim. A participação na GeNtE Comunidade é 100% gratuita. Não cobramos mensalidades, taxas ou qualquer outro valor.", "question": "A participação é gratuita?"}, {"answer": "Não. A comunidade é aberta a profissionais, empreendedores e prestadores de serviços de diversas áreas.", "question": "Preciso ser empresário?"}, {"answer": "Sim, dentro das diretrizes da comunidade. O foco é apresentar seu trabalho de forma colaborativa, gerando conexões e indicações.", "question": "Posso divulgar meu trabalho?"}, {"answer": "Basta preencher o formulário desta página. Você receberá o convite para entrar no grupo aberto no WhatsApp.", "question": "Como participo?"}, {"answer": "Não. A Comunidade é independente. O HUB e o Premium são camadas adicionais do ecossistema, para quem quiser aprofundar relacionamentos e oportunidades.", "question": "Preciso participar do HUB ou Premium?"}], "title": "Dúvidas frequentes. **Tudo o que você precisa saber**.", "contacts": [{"label": "E-mail", "value": "gentenetworking@gmail.com"}, {"label": "WhatsApp", "value": "+55 (51) 2165 2325"}], "subtitle": "Reunimos as principais dúvidas sobre a GeNtE Comunidade para que você entre com confiança e aproveite ao máximo."}, "form": {"title": "Comece hoje a **ampliar sua rede de contatos**.", "benefits": [{"icon": "badge", "title": "100% gratuito", "description": "Participação gratuita, sem mensalidades e sem taxas."}, {"icon": "shield", "title": "Seguro e confiável", "description": "Ambiente verificado e moderado para garantir conexões de qualidade."}, {"icon": "arrow", "title": "Comece agora", "description": "Leva menos de 2 minutos para entrar e fazer parte da nossa comunidade."}], "subtitle": "Entre gratuitamente para o GeNtE Comunidade e faça parte de um ambiente onde conexões podem se transformar em **relacionamentos, parcerias e oportunidades**.", "buttonText": "Entrar gratuitamente na comunidade"}, "hero": {"title": "As **melhores oportunidades** surgem através das indicações de pessoas que conhecem e **confiam no seu trabalho**.", "imageUrl": "https://kcnoqgnrwdjphjzqjnle.supabase.co/storage/v1/object/public/media-library/1781456022738-5hql1aftenp.png", "subtitle": "O **GeNtE Comunidade** reúne profissionais, empreendedores e prestadores de serviços que desejam ampliar sua rede de contatos, aumentar sua visibilidade e criar novas oportunidades através do networking.", "buttonText": "Entrar gratuitamente na comunidade", "highlights": ["Participação gratuita", "Grupo aberto no WhatsApp", "Networking com alcance nacional", "Porta de entrada para o ecossistema GeNtE"]}, "problem": {"title": "Ser excelente no que faz **não é suficiente**.", "points": ["Sem visibilidade, não existem indicações.", "Sem indicações, o crescimento depende apenas da prospecção individual.", "Isso gera desgaste, perde tempo e limita o crescimento."], "callout": "Pessoas não indicam quem **não conhecem**.", "imageUrl": "https://kcnoqgnrwdjphjzqjnle.supabase.co/storage/v1/object/public/media-library/1781456025945-1wup7q8keds.png", "subtitle": "Muitos profissionais dominam sua atividade, entregam resultados e atendem bem seus clientes. Mesmo assim, enfrentam dificuldades para gerar novas oportunidades porque **poucas pessoas conhecem seu trabalho**.", "calloutSubtitle": "A visibilidade é o primeiro passo para gerar conexões, indicações e novas oportunidades."}, "reasons": {"title": "Não é apenas uma comunidade. É um **movimento de conexões** que gera valor.", "reasons": [{"icon": "users", "title": "Amplie sua rede", "description": "Conecte-se com profissionais de diversas áreas e regiões do Brasil."}, {"icon": "handshake", "title": "Gere oportunidades", "description": "Seja indicado, encontre parceiros e descubra novas oportunidades de negócios."}, {"icon": "star", "title": "Aprenda e cresça", "description": "Tenha acesso a conteúdos, eventos e experiências que impulsionam sua evolução profissional."}, {"icon": "trending", "title": "Aumente sua visibilidade", "description": "Mostre seu trabalho, construa autoridade e seja lembrado quando surgirem oportunidades."}, {"icon": "shield", "title": "Fortaleça sua presença", "description": "Esteja em um ambiente colaborativo, ético e focado em crescimento contínuo."}, {"icon": "arrow", "title": "Transforme conexões em resultados", "description": "Aqui, conexões se transformam em relacionamentos e relacionamentos geram resultados reais."}], "subtitle": "No GeNtE Comunidade, acreditamos que relacionamentos verdadeiros abrem portas, geram oportunidades e transformam negócios."}, "audience": {"title": "A comunidade é para **você que quer crescer através de conexões**.", "subtitle": "Profissionais, empreendedores e prestadores de serviços de diversas áreas que acreditam no poder das relações para gerar oportunidades reais.", "audiences": [{"title": "Advogados", "description": "Amplie sua rede, troque experiências e receba indicações qualificadas."}, {"title": "Consultores", "description": "Compartilhe conhecimento, faça parcerias e gere novos negócios."}, {"title": "Corretores", "description": "Conecte-se com outros profissionais e tenha mais oportunidades de vendas."}, {"title": "Psicólogos", "description": "Fortaleça sua presença profissional e seja indicado com confiança."}, {"title": "Contadores", "description": "Aumente sua visibilidade e conquiste novos clientes e parceiros."}, {"title": "E muito mais!", "description": "Empreendedores e prestadores de serviços de todas as áreas são bem-vindos."}]}, "benefits": {"cards": [{"icon": "megaphone", "title": "Apresentação de negócios", "description": "Apresente seu trabalho, compartilhe o que faz e seja encontrado por profissionais que podem indicar seus serviços."}, {"icon": "users", "title": "Networking", "description": "Conecte-se com profissionais de diversas áreas, troque contatos e construa relacionamentos de valor."}, {"icon": "message", "title": "Compartilhamento de experiências", "description": "Aprenda com histórias reais, troque insights e cresça com a jornada de outros profissionais."}, {"icon": "calendar", "title": "Eventos", "description": "Participe de encontros online e ações especiais que geram conexões e oportunidades qualificadas."}, {"icon": "handshake", "title": "Reuniões 1 a 1", "description": "Agende conversas individuais para aprofundar conexões e criar oportunidades reais de parceria."}, {"icon": "star", "title": "Aprendizado sobre networking", "description": "Tenha acesso a conteúdos práticos e dicas para aprimorar suas conexões e sua presença profissional."}], "title": "Um ambiente para **ampliar sua visibilidade** e criar **conexões de valor**.", "footer": "Aqui, conexões se transformam em relacionamentos e relacionamentos geram **oportunidades**.", "subtitle": "O GeNtE Comunidade oferece diversas oportunidades para você se conectar, compartilhar e crescer junto com outros profissionais.", "highlight": "Mais visibilidade. Mais relacionamentos. **Mais oportunidades** para o seu negócio."}, "authority": {"stats": [{"icon": "calendar", "label": "de atuação conectando pessoas e oportunidades desde 2017.", "value": "Mais de 7 anos"}, {"icon": "map", "label": "Participantes de diversas regiões do Brasil, conectando mercados e experiências.", "value": "Alcance nacional"}, {"icon": "users", "label": "Relacionamentos que geram indicações, parcerias e novas oportunidades.", "value": "Centenas de conexões"}, {"icon": "network", "label": "Uma jornada completa para transformar conexões em relacionamentos, parcerias e oportunidades.", "value": "Ecossistema estruturado"}], "title": "Mais de **7 anos** conectando profissionais, empreendedores e oportunidades em **todo o Brasil**.", "subtitle": "O **GeNtE Networking** reúne participantes de diferentes regiões do país, criando conexões que ampliam mercados, fortalecem relacionamentos e geram novas oportunidades."}, "ecosystem": {"steps": [{"icon": "users", "badge": "Participação gratuita", "title": "GeNtE Comunidade", "subtitle": "Conecte-se e seja visto.", "badgeColor": "#1e3a8a", "description": "Participe gratuitamente da comunidade, amplie sua rede de contatos, compartilhe conhecimento e seja referenciado por profissionais de diversas áreas."}, {"icon": "star", "badge": "Assinatura Premium", "title": "GeNtE Hub", "subtitle": "Aprofunde e colabore.", "badgeColor": "#7c3aed", "description": "Tenha acesso a conteúdos exclusivos, eventos, mentorias, grupos estratégicos e ferramentas que impulsionam seus relacionamentos e resultados."}, {"icon": "crown", "badge": "Experiência Exclusiva", "title": "GeNtE Premium", "subtitle": "Conecte-se ao que há de melhor.", "badgeColor": "#c9a84c", "description": "Tenha acesso à nossa curadoria de relacionamentos, networking estratégico e oportunidades de alto nível para acelerar sua evolução profissional."}], "title": "Um ecossistema completo **para conectar, crescer e prosperar**.", "benefits": [{"icon": "network", "text": "Comece na comunidade e evolua no ecossistema que acelera resultados."}, {"icon": "target", "text": "Mais relacionamentos qualificados e mais oportunidades."}, {"icon": "trending", "text": "Cresça com conexões estratégicas em todo o Brasil."}, {"icon": "shield", "text": "Um caminho seguro para relacionamentos que geram negócios."}], "ctaTitle": "Dê o primeiro passo agora.", "subtitle": "O GeNtE Comunidade é a porta de entrada para um ecossistema estruturado que acompanha você em cada etapa da sua jornada profissional, do **primeiro contato às grandes oportunidades**.", "ctaButton": "Entrar gratuitamente na comunidade", "ctaSubtitle": "Sua próxima grande oportunidade pode começar com uma **conexão**."}, "testimonials": {"stats": [{"label": "conectando profissionais e oportunidades", "value": "+7 anos"}, {"label": "participantes de todas as regiões do Brasil", "value": "De norte a sul"}, {"label": "de conexões e parcerias realizadas todos os dias", "value": "Centenas"}, {"label": "sólido e estruturado para relacionamentos que geram resultados", "value": "Um ecossistema"}], "title": "Quem participa, **recomenda**. Histórias reais que geram novas conexões.", "subtitle": "Veja o que nossos participantes dizem sobre as conexões, oportunidades e relacionamentos que construíram aqui.", "testimonials": [{"city": "São Paulo – SP", "name": "Ricardo A.", "role": "Advogado", "text": "Consegui novas parcerias e clientes através de conexões que fiz na comunidade. Hoje, meu negócio é resultado dessas relações."}, {"city": "Curitiba – PR", "name": "Juliana M.", "role": "Consultora de Negócios", "text": "A comunidade me trouxe visibilidade e me conectou com pessoas incríveis que indicam meu trabalho com confiança."}, {"city": "Belo Horizonte – MG", "name": "Marcos T.", "role": "Corretor de Imóveis", "text": "Participo dos eventos e grupos estratégicos e isso me ajuda a aprender, compartilhar e gerar oportunidades todos os dias."}, {"city": "Salvador – BA", "name": "Carla S.", "role": "Psicóloga", "text": "Mais do que contatos, eu encontrei uma rede de apoio profissional que realmente faz a diferença."}]}}'::jsonb,'2026-06-12T15:40:42.71015+00:00','2026-06-14T20:47:11.3752+00:00'),
('4cec8d07-d67b-4eda-8136-601557c66fd7','7e0619ff-7567-4fad-a776-6c211431be94','{"faq": {"faqs": [{"answer": "O lançamento oficial é em 15/09, com o primeiro encontro às 19:30.", "question": "Quando o Gente Impulso começa?"}, {"answer": "100% online e ao vivo, uma vez por quinzena, das 19:30 às 21h.", "question": "Qual é o formato dos encontros?"}, {"answer": "Cada segmento profissional (advocacia, contabilidade, arquitetura etc.) tem apenas uma vaga no grupo, garantindo confiança e zero concorrência interna.", "question": "Como funciona a exclusividade por segmento?"}, {"answer": "Preencha o formulário desta página. Nosso time entra em contato para uma conversa de qualificação e, se houver vaga no seu segmento, você é convidado a entrar.", "question": "Como faço para participar?"}, {"answer": "O valor é apresentado na conversa de qualificação, junto com todos os detalhes de participação e benefícios inclusos.", "question": "Qual é o investimento?"}, {"answer": "Sim. O Impulso é o primeiro grupo do ecossistema Gente com encontros noturnos, pensado para quem não consegue participar de reuniões pela manhã.", "question": "É diferente do Gente Networking tradicional?"}], "title": "Perguntas **frequentes**", "contacts": [{"label": "WhatsApp", "value": "+55 51 2165-2325"}, {"label": "E-mail", "value": "contato@gentenetworking.com.br"}], "subtitle": "Tudo o que você precisa saber antes de garantir sua vaga no Gente Impulso."}, "form": {"title": "Garanta sua vaga no **lançamento 15/09**", "benefits": [{"icon": "badge", "title": "Vaga única por segmento", "description": "Sua área pode ser preenchida a qualquer momento."}, {"icon": "network", "title": "Formato 100% online", "description": "Encontros das 19:30 às 21h, sem deslocamento."}, {"icon": "users", "title": "Ecossistema Gente", "description": "Apoio de uma rede consolidada com anos de operação."}], "subtitle": "Preencha o formulário e nosso time entra em contato para conhecer seu perfil e confirmar a disponibilidade no seu segmento.", "buttonText": "Quero garantir minha vaga"}, "hero": {"title": "E se o seu próximo **grande negócio** começar **à noite**?", "imageUrl": "https://kcnoqgnrwdjphjzqjnle.supabase.co/storage/v1/object/public/media-library/1768490884426-95h2xpcak49.jpg", "subtitle": "Dia **15/09**, o Gente Networking lança seu primeiro grupo noturno.", "buttonText": "Quero garantir minha vaga", "highlights": ["Grupo premium por indicação", "100% online e ao vivo", "Lançamento em 15/09", "Uma vaga por segmento"]}, "problem": {"title": "Sua **rotina** não deixa espaço para networking **pela manhã**?", "points": ["Sua manhã é dedicada aos clientes?", "Sua agenda começa cedo e já está cheia?", "O horário comercial é o momento em que seu negócio mais exige você?", "Você quer fazer networking, mas precisa de um horário diferente?"], "callout": "E aí a agenda vence o networking.", "subtitle": "Os grupos do Gente Networking pela manhã já conectam profissionais e geram negócios todos os dias. Mas sabemos que **nem todo mundo consegue encaixar esse horário na agenda**.\n\nAtendimento a clientes, reuniões, compromissos e a própria rotina do negócio fazem com que muitos profissionais precisem de uma alternativa.\n\n**E foi pensando neles que criamos uma nova possibilidade de fazer parte do Gente.**", "calloutSubtitle": "Se o dia não permite, talvez a noite seja o seu melhor momento para criar novas conexões e gerar negócios."}, "reasons": {"title": "5 razões para entrar no **Gente Impulso** agora", "reasons": [{"icon": "calendar", "title": "Horário que cabe na sua rotina", "description": "19:30 às 21h, uma vez por quinzena, sem atrapalhar seu dia produtivo."}, {"icon": "badge", "title": "Exclusividade por segmento", "description": "Só um profissional por área. Confiança e zero concorrência interna."}, {"icon": "crown", "title": "Curadoria premium", "description": "Entrada por indicação. Você senta em uma sala com pessoas que geram negócio."}, {"icon": "map", "title": "Alcance nacional", "description": "Formato online conecta você com profissionais de todo o Brasil."}, {"icon": "star", "title": "Metodologia validada", "description": "7+ anos de experiência do ecossistema Gente aplicados ao grupo."}, {"icon": "arrow", "title": "Transforme conexões em resultados", "description": "Aqui, conexões se transformam em relacionamentos e relacionamentos geram resultados reais."}], "subtitle": "Vagas limitadas por segmento. Quem entra no lançamento define a régua do grupo."}, "audience": {"title": "Para quem é o **Gente Impulso**", "subtitle": "Profissionais e empreendedores que produzem durante o dia e querem construir rede de indicações à noite, sem sair de casa.", "audiences": [{"title": "Advogados(as)", "description": "Que atendem clientes o dia inteiro e querem gerar indicações qualificadas."}, {"title": "Contadores(as)", "description": "Buscando parcerias estratégicas com outros profissionais liberais."}, {"title": "Corretores(as) de imóveis e seguros", "description": "Que dependem de rede de relacionamento para fechar negócios."}, {"title": "Arquitetos(as) e engenheiros(as)", "description": "Interessados em conectar-se com fornecedores e clientes qualificados."}, {"title": "Consultores(as) e mentores(as)", "description": "Que vendem serviços de alto valor e precisam de indicações constantes."}, {"title": "Empresários(as) e sócios(as)", "description": "Com agenda cheia de dia e disposição para construir rede à noite."}]}, "benefits": {"cards": [{"icon": "users", "title": "Encontros ao vivo", "description": "Reuniões quinenais online das 19:30 às 21h, com pauta estruturada e apresentações rápidas."}, {"icon": "network", "title": "Indicações qualificadas", "description": "Você recebe negócios de dentro da rede, com contexto e relacionamento — não lead frio."}, {"icon": "badge", "title": "Exclusividade por segmento", "description": "Apenas um profissional por área. Sem concorrência interna, com confiança total."}, {"icon": "crown", "title": "Comunidade premium", "description": "Curadoria por indicação. Você entra em uma sala com quem realmente movimenta negócios."}, {"icon": "star", "title": "Mentoria e troca", "description": "Encontros temáticos, mentorias e capacitação em vendas por indicação."}, {"icon": "map", "title": "Sem sair de casa", "description": "100% online. Otimize seu tempo e ganhe conexão nacional, não só local."}], "title": "O Gente Impulso resolve isso com **encontros noturnos e online**", "footer": "Vagas limitadas por segmento - exclusividade garantida.", "subtitle": "90 minutos por quinzena, das 19:30 às 21h, para gerar indicações qualificadas, conhecer parceiros de outros segmentos e crescer com previsibilidade.", "highlight": "Um grupo pensado para profissionais que produzem durante o dia e constroem rede à noite."}, "authority": {"stats": [{"icon": "calendar", "label": "em operação com networking", "value": "desde 2019"}, {"icon": "map", "label": "profissionais de todo o Brasil", "value": "Nacional"}, {"icon": "users", "label": "de profissionais no ecossistema", "value": "Centenas"}, {"icon": "network", "label": "em negócios gerados por indicação", "value": "R$ 15 milhões"}], "title": "**Experiência** em networking. **Milhões** em negócios gerados.   Elas são resultado de experiência, método e das pessoas certas ao seu redor.\n", "subtitle": "O **Gente Impulso** nasce dentro do ecossistema Gente Networking, com anos de experiência conectando profissionais e **milhões em negócios** gerados por indicação."}, "ecosystem": {"steps": [{"icon": "users", "badge": "Participação gratuita", "title": "GeNtE Comunidade", "subtitle": "Conecte-se", "badgeColor": "#1e3a8a", "description": "Rede aberta e gratuita para começar a se relacionar com o ecossistema."}, {"icon": "crown", "badge": "Salas de Conexão", "title": "GeNtE Hub", "subtitle": "Amplifique", "badgeColor": "#00548F", "description": "Tenha acesso a conteúdos exclusivos, eventos, mentorias, grupos estratégicos e ferramentas que impulsionam seus relacionamentos e resultados."}, {"icon": "star", "badge": "Premium — noturno", "title": "GeNtE Impulso", "subtitle": "Acelere à noite", "badgeColor": "#F87512", "description": "Grupo premium noturno, por indicação, com encontros semanais e exclusividade por segmento."}], "title": "Onde o **Impulso** se encaixa no ecossistema Gente", "benefits": [{"icon": "network", "text": "Uma jornada progressiva de relacionamento"}, {"icon": "target", "text": "Mais relacionamentos qualificados e mais oportunidades."}, {"icon": "trending", "text": "Cresça com conexões estratégicas em todo o Brasil."}, {"icon": "shield", "text": "Um caminho seguro para relacionamentos que geram negócios."}], "ctaTitle": "Pronto para acelerar seus negócios à noite?", "subtitle": "Uma jornada progressiva de relacionamento: da comunidade aberta ao grupo premium por indicação.", "ctaButton": "Quero garantir minha vaga", "ctaSubtitle": "Garanta sua vaga no **lançamento de 15/09** antes que seu segmento seja preenchido."}, "testimonials": {"stats": [{"label": "por semana", "value": "90 min"}, {"label": "por segmento", "value": "1x"}, {"label": "online", "value": "100%"}], "title": "O que dizemos que já vivem o **ecossistema Gente**", "subtitle": "Resultados reais de quem transformou networking em negócio previsível.", "testimonials": [{"city": "Porto Alegre/RS", "name": "Marcos A.", "role": "Advogado", "text": "Passei a ter previsibilidade de indicações. O grupo virou parte da minha estratégia comercial."}, {"city": "São Paulo/SP", "name": "Cristina S.", "role": "Contadora", "text": "Encontrei parceiros que hoje trocam clientes comigo toda semana. Vale cada minuto."}, {"city": "Curitiba/PR", "name": "Bruno O.", "role": "Consultor", "text": "O formato online me devolveu tempo. Fecho negócios sem deslocamento, com quem confio."}, {"city": "Uberlândia/MG", "name": "Karoline J.", "role": "Social Media", "text": "Conheci parceiros que abriram portas importantes para meu negócio. Me senti acolhida e venho aprendendo cada vez mais a como fazer networking."}]}}'::jsonb,'2026-07-21T22:49:41.061255+00:00','2026-08-28T12:52:49.987247+00:00');